    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    # Treat each contiguous run of non-background rows as a candidate copy.
    runs = []
    r = 0
    while r < h:
        if any(x != bg for x in grid[r]):
            a = r
            while r < h and any(x != bg for x in grid[r]):
                r += 1
            runs.append((a, r))
        else:
            r += 1

    best = None
    for i in range(len(runs)):
        a0, a1 = runs[i]
        for j in range(i + 1, len(runs)):
            b0, b1 = runs[j]
            if a1 - a0 != b1 - b0:
                continue
            n = a1 - a0
            diff = sum(grid[a0+k][c] != grid[b0+k][c]
                       for k in range(n) for c in range(w))
            if diff == 0:
                continue
            # Select the closest pair of repeated blocks, preferring the one
            # with more matching cells.
            score = (diff, -n)
            if best is None or score < best[0]:
                best = (score, a0, b0, n)

