        # The sparser copy is the damaged one; if tied, use the later copy.
        target, ref = (a0, b0) if ca < cb else (b0, a0)
        for k in range(n):
            for c in range(w):
                if grid[target+k][c] != grid[ref+k][c]:
                    out[target+k][c] = 1
    return out
